using System.IO; using System.Security.Cryptography; using System.Text.Json; using MapCorleon.Data; using MapCorleon.Models; using Microsoft.EntityFrameworkCore;
namespace MapCorleon.Services;
public interface ILocationService { Task<List<Location>> LoadAsync(int mapId,int timelineId,CancellationToken ct=default); Task ToggleMarkedAsync(int id,int timelineId,CancellationToken ct=default); Task<Location> SaveAsync(Location location,CancellationToken ct=default); Task DeleteAsync(int id,CancellationToken ct=default); Task AddMediaAsync(int locationId,string file,CancellationToken ct=default); }
public sealed class LocationService(AppDbContext db,IMediaService media):ILocationService { public Task<List<Location>> LoadAsync(int mapId,int timelineId,CancellationToken ct=default)=>db.Locations.AsNoTracking().Include(x=>x.Category).ThenInclude(x=>x!.Group).Include(x=>x.Media).Include(x=>x.Marks.Where(m=>m.TimelineId==timelineId)).Where(x=>x.Category!.Group!.MapId==mapId&&(!x.IsCustom||x.TimelineId==timelineId)).ToListAsync(ct); public async Task ToggleMarkedAsync(int id,int timelineId,CancellationToken ct=default){var mark=await db.MarkedLocations.SingleOrDefaultAsync(x=>x.LocationId==id&&x.TimelineId==timelineId,ct);if(mark is null)db.Add(new MarkedLocation{LocationId=id,TimelineId=timelineId});else db.Remove(mark);await db.SaveChangesAsync(ct);} public async Task<Location> SaveAsync(Location l,CancellationToken ct=default){if(l.Id==0)db.Add(l);else{var target=await db.Locations.FindAsync([l.Id],ct)??throw new InvalidOperationException("Location no longer exists.");target.Title=l.Title;target.DescriptionMarkdown=l.DescriptionMarkdown;target.CategoryId=l.CategoryId;target.TimelineId=l.TimelineId;target.Latitude=l.Latitude;target.Longitude=l.Longitude;target.IsCustom=l.IsCustom;}await db.SaveChangesAsync(ct);return l;} public async Task DeleteAsync(int id,CancellationToken ct=default){var location=await db.Locations.FindAsync([id],ct);if(location is not null){db.Remove(location);await db.SaveChangesAsync(ct);}} public async Task AddMediaAsync(int id,string file,CancellationToken ct=default){db.Media.Add(await media.StoreAsync(id,file,ct));await db.SaveChangesAsync(ct);} }
public interface ITimelineService { Task<List<Timeline>> LoadAsync(int mapId,CancellationToken ct=default); Task SaveAsync(int mapId,IReadOnlyList<Timeline> timelines,CancellationToken ct=default); }
public sealed class TimelineService(AppDbContext db):ITimelineService { public Task<List<Timeline>> LoadAsync(int mapId,CancellationToken ct=default)=>db.Timelines.Where(x=>x.MapId==mapId).OrderBy(x=>x.SortOrder).ToListAsync(ct); public async Task SaveAsync(int mapId,IReadOnlyList<Timeline> items,CancellationToken ct=default){var existing=await db.Timelines.Where(x=>x.MapId==mapId).ToListAsync(ct);var submittedIds=items.Where(x=>x.Id>0).Select(x=>x.Id).ToHashSet();db.RemoveRange(existing.Where(x=>!submittedIds.Contains(x.Id)));var values=items.Count==0?[new Timeline{MapId=mapId,Name="Default",SortOrder=0}]:items;for(var i=0;i<values.Count;i++){var item=values[i];if(item.Id==0)db.Timelines.Add(new Timeline{MapId=mapId,Name=item.Name,SortOrder=i});else{var target=existing.FirstOrDefault(x=>x.Id==item.Id);if(target is not null){target.Name=item.Name;target.SortOrder=i;}}}await db.SaveChangesAsync(ct);} }
public interface IFilterService { IEnumerable<Location> Apply(IEnumerable<Location> source,MarkFilter filter,IReadOnlyDictionary<int,bool> visibility); }
public sealed class FilterService:IFilterService { public IEnumerable<Location> Apply(IEnumerable<Location>s,MarkFilter f,IReadOnlyDictionary<int,bool>v)=>s.Where(x=>(!v.TryGetValue(x.CategoryId,out var visible)||visible)&&f switch{MarkFilter.Marked=>x.Marks.Count>0,MarkFilter.Unmarked=>x.Marks.Count==0,_=>true}); }
public interface ISearchService { IEnumerable<Location> Search(IEnumerable<Location> source,string? query); }
public sealed class SearchService:ISearchService { public IEnumerable<Location> Search(IEnumerable<Location>s,string?q){if(string.IsNullOrWhiteSpace(q))return s;return s.Where(x=>x.Title.Contains(q,StringComparison.OrdinalIgnoreCase)||x.DescriptionMarkdown.Contains(q,StringComparison.OrdinalIgnoreCase)||x.Category?.Name.Contains(q,StringComparison.OrdinalIgnoreCase)==true||x.Category?.Group?.Name.Contains(q,StringComparison.OrdinalIgnoreCase)==true);} }
public interface ISettingsService { AppSettings Current {get;} Task SaveAsync(AppSettings settings); }
public sealed class JsonSettingsService:ISettingsService { readonly string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"MapCorleon","settings.json"); public AppSettings Current{get;private set;} public JsonSettingsService(){try{Current=JsonSerializer.Deserialize<AppSettings>(File.ReadAllText(path))??AppSettings.Default;}catch{Current=AppSettings.Default;}} public async Task SaveAsync(AppSettings s){Current=s;Directory.CreateDirectory(Path.GetDirectoryName(path)!);Directory.CreateDirectory(s.StorageDirectory);Directory.CreateDirectory(s.TileDirectory);await File.WriteAllTextAsync(path,JsonSerializer.Serialize(s,new JsonSerializerOptions{WriteIndented=true}));} }
public interface IMediaService { Task<Media> StoreAsync(int locationId,string file,CancellationToken ct=default); }
public sealed class MediaService(ISettingsService settings):IMediaService { public async Task<Media> StoreAsync(int id,string file,CancellationToken ct=default){await using var input=File.OpenRead(file);var hash=Convert.ToHexString(await SHA256.HashDataAsync(input,ct));var blobs=Path.Combine(settings.Current.StorageDirectory,"blobs");Directory.CreateDirectory(blobs);var ext=Path.GetExtension(file).ToLowerInvariant();var blob=Path.Combine(blobs,hash+ext);if(!File.Exists(blob))File.Copy(file,blob);var dir=Path.Combine(settings.Current.StorageDirectory,"locations",id.ToString());Directory.CreateDirectory(dir);var link=Path.Combine(dir,hash+ext);if(!File.Exists(link))File.Copy(blob,link);return new Media{LocationId=id,ContentHash=hash,RelativePath=link};} }
public interface ITileCacheService { Task<byte[]?> GetAsync(string provider,int zoom,int x,int y,Func<CancellationToken,Task<byte[]?>> remote,CancellationToken ct=default); Task ClearExpiredAsync(CancellationToken ct=default); }
public sealed class TileCacheService(ISettingsService settings):ITileCacheService { public async Task<byte[]?> GetAsync(string p,int z,int x,int y,Func<CancellationToken,Task<byte[]?>> remote,CancellationToken ct=default){var f=Path.Combine(settings.Current.TileDirectory,p,z.ToString(),x.ToString(),$"{y}.tile");if(File.Exists(f)&&DateTime.UtcNow-File.GetLastWriteTimeUtc(f)<settings.Current.TileMaxAge)return await File.ReadAllBytesAsync(f,ct);var data=await remote(ct);if(data is not null){Directory.CreateDirectory(Path.GetDirectoryName(f)!);await File.WriteAllBytesAsync(f,data,ct);}return data;} public Task ClearExpiredAsync(CancellationToken ct=default){if(!Directory.Exists(settings.Current.TileDirectory))return Task.CompletedTask;foreach(var f in Directory.EnumerateFiles(settings.Current.TileDirectory,"*.tile",SearchOption.AllDirectories).Where(f=>DateTime.UtcNow-File.GetLastWriteTimeUtc(f)>=settings.Current.TileMaxAge))File.Delete(f);return Task.CompletedTask;} }
public interface IEventBus { event EventHandler<Location?>? SelectionChanged; void Select(Location? location); }
public sealed class EventBus:IEventBus { public event EventHandler<Location?>? SelectionChanged; public void Select(Location? l)=>SelectionChanged?.Invoke(this,l); }
